package com.expensetracker.controller;
import com.expensetracker.dto.*;import com.expensetracker.service.BudgetService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/budgets") public class BudgetController {private final BudgetService s;public BudgetController(BudgetService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public BudgetResponseDTO create(@Valid @RequestBody BudgetRequestDTO r){return s.create(r);}@GetMapping public List<BudgetResponseDTO> all(@RequestParam Long userId,@RequestParam(required=false) Integer month,@RequestParam(required=false) Integer year){return s.all(userId,month,year);}@PutMapping("/{id}") public BudgetResponseDTO update(@PathVariable Long id,@Valid @RequestBody BudgetRequestDTO r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@RequestParam Long userId){s.delete(id,userId);}}
